"""Offline path worker.  Arrays store traffic amounts, not fractions.

The captured problem of one immutable issue is

    minimise  f = 0.5*sum x**2 + 0.5*rho*sum_{e:c[e]>0}(L[e]/c[e]-B[e])**2 - R
    subject to  sum_p x[k,p] = d[k]   (route)   /   <= d[k]   (admit),  x >= 0,

with `L` the worker's own TOTAL path load and `B` its captured normalized bias.
`admit` gains one zero-cost slack per commodity, which turns the inequality into
an equality row whose multiplier is exactly the certified potential.
"""
from __future__ import annotations

from typing import Dict, List, Optional, Sequence, Tuple

import numpy as np

from array_utils.cpu.types import CPUArray
from te.algorithms.sub_algorithms.active_set import active_set_qp
from te.algorithms.sub_algorithms.pgd import do_path_based_nesterov_pgd
from te.algorithms.sub_algorithms.simplex_projection import project_groups
from te.path_providers.base import PathProvider
from te.path_providers.sparse_ops import (
    dense_incidence,
    normalized_utilization,
    total_edge_load,
)


def tolerance(a: float, b: float) -> float:
    return 1e-7 + 1e-7 * max(abs(float(a)), abs(float(b)))


class CapturedProblem:
    """Immutable snapshot data of a single issued ticket."""

    def __init__(self, provider: PathProvider, capacities: Sequence[int], demands: Sequence[float],
                 owned: Sequence[int], bias: Sequence[float], mode: str, rho: float):
        self.provider = provider
        self.num_edges = provider.num_edges
        self.capacities = [int(c) for c in capacities]
        self.demands = [float(d) for d in demands]
        self.owned = [int(k) for k in owned]
        self.bias = np.array([float(b) for b in bias], dtype=np.float64)
        self.mode = mode
        self.admit = mode == 'admit'
        self.rho = float(rho)
        self.live = [self.capacities[e] > 0 for e in range(self.num_edges)]
        self._prepare()

    # ------------------------------------------------------------- structure
    def _prepare(self) -> None:
        groups: List[Tuple[int, int, float, List[Tuple[int, Tuple[int, ...]]]]] = []
        unroutable: List[int] = []
        for j, k in enumerate(self.owned):
            slots = []
            for t in range(self.provider.slot_count(k)):
                path = self.provider.path(k, t)
                if path is not None and all(self.live[e] for e in path):
                    slots.append((t, path))
            demand = self.demands[j]
            if demand > 0.0:
                if slots:
                    groups.append((j, k, demand, slots))
                else:
                    unroutable.append(k)
        self.groups = groups
        self.unroutable = sorted(unroutable)
        self.members: List[List[int]] = []
        self.slot_paths: List[Tuple[int, ...]] = []
        self.variable_of: Dict[Tuple[int, int], int] = {}
        for j, (_j, _k, _d, slots) in enumerate(groups):
            idx = []
            for t, path in slots:
                self.variable_of[(j, t)] = len(self.slot_paths)
                self.slot_paths.append(path)
                idx.append(len(self.slot_paths) - 1)
            self.members.append(idx)
        self.nvar = len(self.slot_paths)
        self.ngroups = len(groups)
        self.group_demand = np.array([g[2] for g in groups], dtype=np.float64)
        # bias and inverse capacity restricted to live edges
        bias = np.zeros(self.num_edges, dtype=np.float64)
        inverse = np.zeros(self.num_edges, dtype=np.float64)
        for e in range(self.num_edges):
            if self.live[e]:
                bias[e] = self.bias[e]
                inverse[e] = 1.0 / float(self.capacities[e])
        self.bias_live = bias
        self.inverse = inverse
        if self.nvar:
            self.incidence = dense_incidence(self.slot_paths, self.num_edges)
            scaled = self.incidence * inverse
            self.hessian = np.eye(self.nvar) + self.rho * (scaled @ scaled.T)
            self.linear = -self.rho * (scaled @ bias) - (1.0 if self.admit else 0.0)
        else:
            self.incidence = np.zeros((0, self.num_edges), dtype=np.float64)
            self.hessian = np.zeros((0, 0), dtype=np.float64)
            self.linear = np.zeros(0, dtype=np.float64)

    def feasible(self) -> bool:
        return self.admit or not self.unroutable

    # -------------------------------------------------------------- objective
    def load(self, amounts: np.ndarray) -> np.ndarray:
        return total_edge_load(amounts, self.slot_paths, self.num_edges, self.live)

    def utilization(self, amounts: np.ndarray) -> np.ndarray:
        return normalized_utilization(self.load(amounts), np.array(self.capacities, dtype=np.float64),
                                      self.live)

    def derivative(self, amounts: np.ndarray) -> np.ndarray:
        residual = np.zeros(self.num_edges, dtype=np.float64)
        util = self.utilization(amounts)
        for e in range(self.num_edges):
            if self.live[e]:
                residual[e] = (util[e] - self.bias_live[e]) * self.inverse[e]
        extra = float(self.rho) * (self.incidence @ residual) if self.nvar else residual[:0]
        base = np.array(amounts, dtype=np.float64) - (1.0 if self.admit else 0.0)
        return base + extra if self.nvar else base

    def objective(self, amounts: np.ndarray) -> float:
        util = self.utilization(amounts)
        gap = np.zeros(self.num_edges, dtype=np.float64)
        for e in range(self.num_edges):
            if self.live[e]:
                gap[e] = util[e] - self.bias_live[e]
        value = 0.5 * float(np.dot(amounts, amounts)) + 0.5 * self.rho * float(np.dot(gap, gap))
        if self.admit:
            value -= float(np.sum(amounts))
        return value

    # -------------------------------------------------------------- equality
    def equality_system(self) -> Tuple[np.ndarray, np.ndarray, np.ndarray, np.ndarray]:
        """``H, g, A, b`` of the admit-slack (or plain route) equality form."""
        n, m = self.nvar, self.ngroups
        total = n + m if self.admit else n
        H = np.zeros((total, total), dtype=np.float64)
        H[:n, :n] = self.hessian
        g = np.zeros(total, dtype=np.float64)
        g[:n] = self.linear
        A = np.zeros((m, total), dtype=np.float64)
        for j in range(m):
            for i in self.members[j]:
                A[j, i] = 1.0
            if self.admit:
                A[j, n + j] = 1.0
        return H, g, A, self.group_demand.copy()

    def project(self, amounts: np.ndarray) -> np.ndarray:
        return project_groups(np.asarray(amounts, dtype=np.float64), self.members,
                              self.group_demand, self.admit)


def _certificate_score(problem: CapturedProblem, x: np.ndarray, gradient: np.ndarray,
                       potentials: np.ndarray, value: float) -> float:
    """Worst normalized violation of feasibility, G+lambda>=0 and f==D."""
    residual = 0.0
    for j, members in enumerate(problem.members):
        lam = float(potentials[j])
        for i in members:
            residual += float(x[i]) * (float(gradient[i]) + lam)
    other = value - residual
    score = abs(value - other) / tolerance(value, other)
    for j, members in enumerate(problem.members):
        lam = float(potentials[j])
        mass = float(sum(float(x[i]) for i in members))
        demand = float(problem.group_demand[j])
        if problem.admit:
            if mass > demand:
                score = max(score, (mass - demand) / tolerance(mass, demand))
        else:
            score = max(score, abs(mass - demand) / tolerance(mass, demand))
        if lam < 0.0 and problem.admit:
            score = max(score, abs(lam) / tolerance(lam, 0.0))
        for i in members:
            gap = -(float(gradient[i]) + lam)
            if gap > 0.0:
                score = max(score, gap / tolerance(gradient[i], lam))
    return score


def _potential_candidates(problem: CapturedProblem, x: np.ndarray, gradient: np.ndarray,
                          kkt: np.ndarray) -> List[np.ndarray]:
    out: List[np.ndarray] = []
    m = problem.ngroups
    if m == 0:
        return out

    def finalize(values: Sequence[float]) -> np.ndarray:
        arr = np.array([float(v) for v in values], dtype=np.float64)
        if problem.admit:
            arr = np.maximum(arr, 0.0)
        return arr

    if kkt is not None and len(kkt) == m:
        out.append(finalize(kkt))
    minima = []
    positives = []
    means = []
    for members in problem.members:
        values = [float(gradient[i]) for i in members]
        minima.append(-min(values))
        active = [float(gradient[i]) for i in members if float(x[i]) > 0.0]
        positives.append(-min(active) if active else -min(values))
        weighted = sum(float(x[i]) * float(gradient[i]) for i in members)
        means.append(-weighted)
    out.append(finalize(minima))
    out.append(finalize(positives))
    demand = problem.group_demand
    out.append(finalize([means[j] / demand[j] if demand[j] > 0 else 0.0 for j in range(m)]))
    return out


def _polish(problem: CapturedProblem, x: np.ndarray, kkt: Optional[np.ndarray]):
    load = problem.load(x)
    gradient = problem.derivative(x)
    value = problem.objective(x)
    best = None
    for candidate in _potential_candidates(problem, x, gradient, kkt):
        score = _certificate_score(problem, x, gradient, candidate, value)
        if best is None or score < best[0]:
            best = (score, candidate)
    if best is None:
        best = (0.0, np.zeros(problem.ngroups, dtype=np.float64))
    return x, load, gradient, value, best[1], best[0]


def _fallback_amounts(problem: CapturedProblem) -> Optional[np.ndarray]:
    """Accelerated projected gradient, then an active-set polish from it."""
    if problem.nvar == 0:
        return np.zeros(0, dtype=np.float64)
    eigen = np.linalg.eigvalsh(problem.hessian)
    smooth = float(eigen[-1]) if eigen.size else 1.0
    step = 1.0 / max(1.0, smooth)
    start = problem.project(np.zeros(problem.nvar, dtype=np.float64))
    if not problem.admit:
        start = problem.project(problem.group_demand.astype(np.float64) * 0.0 + _spread(problem))
    amounts = do_path_based_nesterov_pgd(
        start, problem.hessian, problem.linear, problem.group_demand, problem.members, step,
        6000, problem.project, None, problem.objective)
    if not np.all(np.isfinite(amounts)):
        return None
    H, g, A, b = problem.equality_system()
    free = np.zeros(H.shape[0], dtype=bool)
    for j, members in enumerate(problem.members):
        for i in members:
            free[i] = amounts[i] > 1e-12 * (1.0 + float(problem.group_demand[j]))
        if problem.admit:
            slack = float(problem.group_demand[j]) - float(sum(amounts[i] for i in members))
            free[problem.nvar + j] = slack > 1e-12 * (1.0 + float(problem.group_demand[j]))
    solution = active_set_qp(H, g, A, b, free0=free)
    if solution.status != 'optimal':
        return np.maximum(problem.project(amounts), 0.0)
    return np.maximum(solution.x[:problem.nvar], 0.0)


def _spread(problem: CapturedProblem) -> np.ndarray:
    """Feasible route start: split each demand evenly over its available slots."""
    out = np.zeros(problem.nvar, dtype=np.float64)
    for j, members in enumerate(problem.members):
        if not members:
            continue
        share = float(problem.group_demand[j]) / len(members)
        for i in members:
            out[i] = share
    return out


class DenseSolver:
    """Solves one captured worker problem and reports its certificate data."""

    def __init__(self, provider: PathProvider, owned: Sequence[int] = ()):
        self.provider = provider
        self._K, self._N, self._T = provider.shape
        self._alpha_shape = provider.shape
        self._alpha_rows, self._alpha_cols = provider.rows, provider.cols
        self._owned = [int(k) for k in owned]
        self._demands = np.zeros(len(self._owned))
        self._scale_with_capacity = False
        self._capacities = np.ones(self._N)
        self.problem: Optional[CapturedProblem] = None
        self.amounts = np.zeros(0, dtype=np.float64)
        self.loads = np.zeros(self._N, dtype=np.float64)
        self.potentials = np.zeros(len(self._owned), dtype=np.float64)
        self.status = 'optimal'
        self.unroutable: List[int] = []
        self.score = 0.0

    def configure(self, capacities, demands, active, target, mode, rho=1, owned=None):
        """Capture `c`, `d`, availability, bias `B`, mode and penalty `rho`."""
        if owned is not None:
            self._owned = [int(k) for k in owned]
        self._capacities = np.array([float(c) for c in capacities], dtype=np.float64)
        self._demands = np.array([float(d) for d in demands], dtype=np.float64)
        self.problem = CapturedProblem(self.provider, capacities, self._demands, self._owned,
                                       target, mode, rho)
        self.active = active
        self._scale_with_capacity = True
        return self

    # -------------------------------------------------------------- solving
    def update(self, converged=None):
        problem = self.problem
        assert problem is not None
        self.potentials = np.zeros(len(self._owned), dtype=np.float64)
        self.loads = np.zeros(self._N, dtype=np.float64)
        if not problem.feasible():
            self.status = 'infeasible'
            self.unroutable = list(problem.unroutable)
            self.amounts = np.zeros(0, dtype=np.float64)
            self.score = 0.0
            return self
        self.status = 'optimal'
        self.unroutable = []
        if problem.nvar == 0:
            self.amounts = np.zeros(0, dtype=np.float64)
            self.loads = problem.load(self.amounts)
            self.score = 0.0
            return self
        H, g, A, b = problem.equality_system()
        solution = active_set_qp(H, g, A, b)
        best = None
        if solution.status == 'optimal':
            x = np.maximum(solution.x[:problem.nvar], 0.0)
            best = _polish(problem, x, solution.multipliers)
        if best is None or best[5] > 0.25:
            alternate = _fallback_amounts(problem)
            if alternate is not None:
                polished = _polish(problem, alternate, None)
                if best is None or polished[5] < best[5]:
                    best = polished
        if best is None:
            best = _polish(problem, np.maximum(_spread(problem), 0.0), None)
        self.amounts, self.loads, _gradient, _value, potentials, self.score = best
        for j, (position, _k, _d, _slots) in enumerate(problem.groups):
            self.potentials[position] = potentials[j]
        return self

    # ------------------------------------------------------------- reporting
    @property
    def conditional_capacity(self) -> Optional[CPUArray]:
        return self._capacities if self._scale_with_capacity else None

    @property
    def X_ek(self) -> CPUArray:
        """Worker TOTAL raw edge load (never an unweighted mean of means)."""
        return self.loads

    @property
    def total_flow(self) -> float:
        return float(np.sum(self.amounts))

    def proposal(self) -> Dict:
        problem = self.problem
        assert problem is not None
        if self.status == 'infeasible':
            return {'status': 'infeasible', 'unroutable': [int(k) for k in self.unroutable]}
        flow: List[List[float]] = []
        for j, k in enumerate(problem.owned):
            row = [0.0] * problem.provider.slot_count(k)
            for t in range(problem.provider.slot_count(k)):
                index = problem.variable_of.get((j, t))
                if index is not None:
                    row[t] = float(self.amounts[index])
            flow.append(row)
        return {
            'status': 'optimal',
            'flow': flow,
            'edge_load': [float(v) for v in self.loads],
            'potential': [float(v) for v in self.potentials],
        }
